"""Feedback matrices for the FDN, generated by :mod:`pyFDN`.

Supported types
---------------
* ``RANDOM``             -- Haar-distributed orthogonal matrix.
* ``HADAMARD``           -- normalised Hadamard (size must be a power of 2).
* ``HOUSEHOLDER``        -- reflection about the all-ones vector.
* ``CIRCULANT``          -- random unit-modulus circulant.
* ``PERMUTATION``        -- random permutation (parallel comb filters, permuted).
* ``DIAGONALLY_SIMILAR`` -- ``D^-1 Q D``; lossless but not orthogonal.
* ``ANDERSON``           -- Anderson's construction.
* ``TINY_ROTATION``      -- near-identity rotation; needs ``torch``.

All generators come from ``pyFDN``.  ``pyFDN`` draws from NumPy's *global*
random state and exposes no seed parameter, so :func:`_seeded` saves that
state, seeds it, and restores it -- keeping this package reproducible without
disturbing the caller's own stream.
"""

from __future__ import annotations

from collections.abc import Callable
from enum import Enum
from typing import Any

import numpy as np
import pyFDN
from numpy.typing import NDArray


class FeedbackMatrixType(str, Enum):
    """Feedback matrix flavour."""

    RANDOM = "random"
    HADAMARD = "hadamard"
    HOUSEHOLDER = "householder"
    CIRCULANT = "circulant"
    PERMUTATION = "permutation"
    DIAGONALLY_SIMILAR = "diagonally_similar"
    ANDERSON = "anderson"
    TINY_ROTATION = "tiny_rotation"

    def __repr__(self) -> str:  # pragma: no cover
        return self.value


#: Types this package delegates straight to ``pyFDN.fdn_matrix_gallery``,
#: mapped to the gallery's own type strings.  ``HOUSEHOLDER`` is deliberately
#: absent: the gallery builds a *random* reflection, while the FDN literature
#: means the one about the all-ones vector.
_GALLERY_TYPES: dict[FeedbackMatrixType, str] = {
    FeedbackMatrixType.RANDOM: "orthogonal",
    FeedbackMatrixType.HADAMARD: "Hadamard",
    FeedbackMatrixType.CIRCULANT: "circulant",
    FeedbackMatrixType.PERMUTATION: "permutation",
    FeedbackMatrixType.DIAGONALLY_SIMILAR: "diagonallySimilarToOrthogonal",
    FeedbackMatrixType.ANDERSON: "Anderson",
    FeedbackMatrixType.TINY_ROTATION: "tinyRotation",
}


def _seeded(fn: Callable[..., Any], seed: int | None, *args: Any, **kwargs: Any) -> Any:
    """Call *fn* with NumPy's global random state seeded, then restore it.

    ``pyFDN``'s matrix generators draw from ``np.random`` and take no seed.
    Saving and restoring the global state around the call makes them
    reproducible here while leaving the caller's stream exactly as it was.
    """
    state = np.random.get_state()
    try:
        np.random.seed(seed)
        return fn(*args, **kwargs)
    finally:
        np.random.set_state(state)


class FeedbackMatrix:
    """Scalar feedback matrix for the FDN.

    Parameters
    ----------
    size : int
        Matrix dimension (*N* x *N*).
    matrix_type : FeedbackMatrixType
        Any member of :class:`FeedbackMatrixType`.
    frame_size : int
        Accepted for signature compatibility; unused since the recursion moved
        to :func:`src.fdn.render.render_fdn`.
    seed : int, optional
        Random seed.  Deterministic types ignore it.

    Attributes
    ----------
    matrix : NDArray
        The *N* x *N* lossless feedback matrix.
    """

    def __init__(
        self,
        size: int,
        matrix_type: FeedbackMatrixType,
        frame_size: int,
        *,
        seed: int | None = None,
    ) -> None:
        self.num_rows = size
        self.num_cols = size
        self.frame_size = frame_size

        if matrix_type == FeedbackMatrixType.HOUSEHOLDER:
            # Not via the gallery: pyFDN's "Householder" reflects about a random
            # vector, whereas the FDN literature means the all-ones one.
            self.matrix = np.asarray(pyFDN.householder_matrix(np.ones(size)), float)
            return

        gallery_type = _GALLERY_TYPES.get(matrix_type)
        if gallery_type is None:
            raise ValueError(f"Unsupported feedback matrix type: {matrix_type}")
        if matrix_type == FeedbackMatrixType.HADAMARD and (
            size < 1 or (size & (size - 1)) != 0
        ):
            raise ValueError(f"Hadamard size must be a power of 2, got {size}.")

        matrix = _seeded(pyFDN.fdn_matrix_gallery, seed, size, gallery_type)
        self.matrix = np.asarray(matrix, dtype=float)

    # -- Verification -------------------------------------------------------

    @staticmethod
    def is_unitary(M: NDArray, tol: float = 1e-9) -> bool:
        """Check *M* is lossless, i.e. *M*^T *M* is a scaled identity.

        Delegates to :func:`pyFDN.is_unilossless`, which admits the lossless
        non-orthogonal matrices (``DIAGONALLY_SIMILAR``) that a plain
        orthogonality test would reject.
        """
        return bool(pyFDN.is_unilossless(np.asarray(M, dtype=float), tol=tol))


def _rotation_blocks(
    matrix: NDArray, tol: float
) -> tuple[NDArray, NDArray, list[tuple[int, int]], list[int]]:
    """Real Schur form of an orthogonal matrix, split into its plane rotations.

    Returns the Schur blocks, the orthogonal basis, the index pairs holding a
    2x2 rotation, and the indices of any 1x1 entries equal to -1.  Those
    negatives determine the determinant's sign -- each rotation block has
    determinant +1, so the sign is ``(-1) ** len(negatives)``.  Reading it from
    here avoids calling ``det`` or ``slogdet``, both of which emit spurious
    overflow warnings on orthogonal matrices of moderate size while returning
    the correct value.
    """
    from scipy.linalg import schur

    blocks, basis = schur(matrix, output="real")
    size = blocks.shape[0]
    rotations: list[tuple[int, int]] = []
    negatives: list[int] = []

    index = 0
    while index < size:
        if index + 1 < size and abs(blocks[index + 1, index]) > tol:
            rotations.append((index, index + 1))
            index += 2
        else:
            if blocks[index, index] < 0.0:
                negatives.append(index)
            index += 1
    return blocks, basis, rotations, negatives


def is_reflection(matrix: NDArray, tol: float = 1e-10) -> bool:
    """True when an orthogonal *matrix* has determinant -1.

    Reflections are not reachable from the identity by a continuous path within
    SO(n), so :func:`interpolate_to_orthogonal` rejects them; flip the sign of
    one column to turn one into a rotation.
    """
    _, _, _, negatives = _rotation_blocks(np.asarray(matrix, dtype=float), tol)
    return len(negatives) % 2 == 1


def interpolate_to_orthogonal(
    target: NDArray, amount: float, tol: float = 1e-10
) -> NDArray:
    """Interpolate from the identity to *target* without leaving SO(n).

    Every matrix in SO(n) is a set of plane rotations in mutually orthogonal
    planes; the real Schur form exposes them as 2x2 blocks along the diagonal.
    Scaling each block's rotation angle by *amount* gives a matrix that is
    orthogonal for every value of it, reaching the identity at 0 and the target
    at 1.

    The obvious alternative, ``real(expm(amount * logm(target)))``, only works
    when *target* has no eigenvalue at -1.  The principal logarithm of -1 is
    complex, so taking the real part of the exponential drops off the manifold.
    A normalised Hadamard matrix is a symmetric involution with eigenvalues
    ``{+1, -1}`` and fails exactly this way -- measured ``||M^T M - I||_F`` of
    1.41 at size 4 and 2.00 at size 8.  Eigenvalues at -1 are handled here by
    pairing them into rotations by ``pi``, which scale like any other.

    Parameters
    ----------
    target : NDArray, shape (n, n)
        Orthogonal matrix with determinant +1.
    amount : float
        Interpolation parameter.  0 gives the identity, 1 gives *target*.
    tol : float
        Threshold for treating a sub-diagonal entry as a rotation block.

    Returns
    -------
    NDArray, shape (n, n)
        Orthogonal, with determinant +1.

    Raises
    ------
    ValueError
        If *target* is not orthogonal, or is a reflection -- see
        :func:`is_reflection`.
    """
    target = np.asarray(target, dtype=float)
    size = target.shape[0]
    if not np.allclose(target.T @ target, np.eye(size), atol=1e-8):
        raise ValueError("interpolate_to_orthogonal needs an orthogonal target.")

    blocks, basis, rotations, negatives = _rotation_blocks(target, tol)
    if len(negatives) % 2:
        raise ValueError(
            "Target has determinant -1: a reflection is not reachable from the "
            "identity by a continuous path within SO(n). Flip the sign of one "
            "column first."
        )

    rotated = np.eye(size)
    for first, second in rotations:
        angle = (
            np.arctan2(blocks[first, second], blocks[first, first]) * amount
        )
        rotated[first, first] = rotated[second, second] = np.cos(angle)
        rotated[first, second] = np.sin(angle)
        rotated[second, first] = -np.sin(angle)

    # A -1 eigenvalue is a rotation by pi with no preferred plane.  With
    # determinant +1 they come in pairs, and each pair spans a plane that can be
    # rotated by amount * pi like any other block.
    angle = np.pi * amount
    for first, second in zip(negatives[::2], negatives[1::2], strict=True):
        rotated[first, first] = rotated[second, second] = np.cos(angle)
        rotated[first, second] = np.sin(angle)
        rotated[second, first] = -np.sin(angle)

    return basis @ rotated @ basis.T
